    (878, 'graduation_sci', 'gsci-sound-concept', 'concept', 1, 'ध्वनि',
     $j${"text":"ध्वनि एक अनुदैर्घ्य यांत्रिक तरंग है जिसे सुना जा सकता है। मनुष्य 20 Hz से 20,000 Hz तक की ध्वनि सुन सकता है। 20 Hz से कम को अवश्रव्य (infrasonic) और 20,000 Hz से अधिक को पराश्रव्य (ultrasonic) कहते हैं। ध्वनि ठोस, द्रव और गैस में चलती है, निर्वात में नहीं।","note":"ध्वनि निर्वात में नहीं चलती"}$j$,
